impl Solution {
  pub fn missing_two(nums: Vec<i32>) -> Vec<i32> {
    let n = nums.len() as i64 + 2;
    let sum_all = n * (n + 1) / 2;
    let sq_all = n * (n + 1) * (2 * n + 1) / 6;
    let sum: i64 = nums.iter().map(|&x| x as i64).sum();
    let sq: i64 = nums.iter().map(|&x| x as i64 * x as i64).sum();
    let ds = sum_all - sum;
    let dq = sq_all - sq;
    let diff = ((2 * dq - ds * ds) as f64).sqrt() as i64;
    let a = ((ds + diff) / 2) as i32;
    let b = (ds - a as i64) as i32;
    vec![a, b]
  }
}

const missingTwo = (nums: number[]): number[] => {
  const n = nums.length + 2;
  const sumAll = (n * (n + 1)) / 2;
  const sqAll = (n * (n + 1) * (2 * n + 1)) / 6;
  let sum = 0;
  let sq = 0;
  for (const x of nums) {
    sum += x;
    sq += x * x;
  }
  const ds = sumAll - sum;
  const dq = sqAll - sq;
  const diff = Math.round(Math.sqrt(2 * dq - ds * ds));
  const a = Math.round((ds + diff) / 2);
  const b = ds - a;
  return [a, b];
};
